//! Reading and writing the stack `.env` files, plus host defaults.

use std::collections::BTreeMap;
use std::ffi::OsString;
use std::fs;
use std::io;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};

pub type EnvMap = BTreeMap<String, String>;

/// Where generated stack state lives when churn is not run from a checkout.
pub const DEFAULT_ROOT: &str = "/var/lib/churn";

const PREAMBLE: &str = "\
# Generated by churn — rerun the installer to update.
# Safe to edit by hand; keys churn doesn't manage are preserved on rerun.";

/// Root for all generated stack state (`server/`, `torrent/`, `.env` files).
///
/// `CHURN_ROOT` wins so tests and custom installs can choose a location. When
/// churn is run from a checkout, the current directory is used so development
/// does not write into `/var/lib/churn`. A released binary run anywhere else
/// installs under [`DEFAULT_ROOT`].
pub fn root() -> PathBuf {
    let cwd = std::env::current_dir().ok();
    root_for(std::env::var_os("CHURN_ROOT"), cwd.as_deref())
}

fn root_for(override_root: Option<OsString>, cwd: Option<&Path>) -> PathBuf {
    if let Some(dir) = override_root.filter(|dir| !dir.is_empty()) {
        return PathBuf::from(dir);
    }
    if let Some(dir) = cwd.filter(|dir| is_checkout(dir)) {
        return dir.to_path_buf();
    }
    PathBuf::from(DEFAULT_ROOT)
}

fn is_checkout(dir: &Path) -> bool {
    dir.join("server/docker-compose.yml").is_file()
        && dir.join("torrent/docker-compose.yml").is_file()
}

pub fn read(path: &Path) -> EnvMap {
    let Ok(contents) = fs::read_to_string(path) else {
        return EnvMap::new();
    };
    parse(&contents)
}

/// Parse `.env` text, ignoring blanks, comments and lines without a separator.
pub fn parse(contents: &str) -> EnvMap {
    contents
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty() && !line.starts_with('#') && line.contains('='))
        .filter_map(|line| {
            let (key, value) = line.split_once('=')?;
            Some((key.trim().to_string(), value.trim().to_string()))
        })
        .collect()
}

/// Read a storage path from an env map, accepting the pre-`MEDIA_DIR` key.
///
/// Installations created before the download/media split stored one path under
/// `DATA_DIR`. Reading it as the download directory keeps a rerun from losing
/// the user's existing location, and `Stack::apply` rewrites the file with the
/// new key so the legacy value never lingers.
pub fn storage_path(env: &EnvMap, key: &str) -> Option<String> {
    let read = |env: &EnvMap, name: &str| {
        env.get(name)
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty())
    };
    read(env, key).or_else(|| {
        if key == "DOWNLOAD_DIR" {
            read(env, "DATA_DIR")
        } else {
            None
        }
    })
}

/// Write `managed` keys in order, keeping any unrelated keys from a previous run.
pub fn write_merged(path: &Path, managed: &[(&str, String)]) -> io::Result<()> {
    write_merged_dropping(path, managed, &[])
}

/// [`write_merged`] with keys that must not survive from the previous file.
///
/// Used when a managed set changes shape — a VPN provider switch leaves the
/// other protocol's credentials behind — so the old keys are deleted rather
/// than preserved by the generic "keep unrelated keys" rule.
pub fn write_merged_dropping(
    path: &Path,
    managed: &[(&str, String)],
    extra_dropped: &[&str],
) -> io::Result<()> {
    let existing = read(path);
    // A pre-split install stored one path under `DATA_DIR`. Once `DOWNLOAD_DIR`
    // is managed, the old key must go: keeping it under "preserved" would leave
    // two keys claiming the same thing.
    let mut dropped: Vec<&str> = if managed.iter().any(|(key, _)| *key == "DOWNLOAD_DIR") {
        vec!["DATA_DIR"]
    } else {
        Vec::new()
    };
    dropped.extend_from_slice(extra_dropped);
    let extras: Vec<(&String, &String)> = existing
        .iter()
        .filter(|(key, _)| {
            !dropped.contains(&key.as_str())
                && !managed
                    .iter()
                    .any(|(managed_key, _)| managed_key == &key.as_str())
        })
        .collect();

    let mut out = String::from(PREAMBLE);
    out.push_str("\n\n");
    for (key, value) in managed {
        out.push_str(&format!("{key}={value}\n"));
    }
    if !extras.is_empty() {
        out.push_str("\n# preserved from previous file\n");
        for (key, value) in extras {
            out.push_str(&format!("{key}={value}\n"));
        }
    }

    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(path, out)?;
    // Every stack `.env` holds a secret — the WireGuard private key or the
    // Jellyfin admin password — so a freshly created file must not inherit the
    // umask's 0644 and be readable by every local user.
    restrict(path)
}

/// Make `path` owner-only (0600).
pub fn restrict(path: &Path) -> io::Result<()> {
    fs::set_permissions(path, fs::Permissions::from_mode(0o600))
}

/// Set one key in place, preserving comments, ordering and every other key.
///
/// Used after installation for values that only exist once a container has
/// started, such as Jellyfin's generated API key.
pub fn upsert(path: &Path, key: &str, value: &str) -> io::Result<()> {
    upsert_many(path, &[(key, value)])
}

/// Set several keys in one atomic rewrite, preserving everything else.
///
/// The temporary file lives beside the target so the rename never crosses a
/// filesystem boundary, and the existing mode is carried over so secrets do not
/// become world-readable during a migration.
pub fn upsert_many(path: &Path, values: &[(&str, &str)]) -> io::Result<()> {
    let existing = fs::read_to_string(path).unwrap_or_default();
    let mut out = String::with_capacity(existing.len() + 64 * values.len());
    let mut found: Vec<bool> = vec![false; values.len()];

    for line in existing.lines() {
        let name = line.split_once('=').map(|(name, _)| name.trim());
        if let Some(index) = name.and_then(|name| values.iter().position(|(key, _)| *key == name)) {
            out.push_str(&format!("{}={}", values[index].0, values[index].1));
            found[index] = true;
        } else {
            out.push_str(line);
        }
        out.push('\n');
    }

    for (index, (key, value)) in values.iter().enumerate() {
        if !found[index] {
            out.push_str(&format!("{key}={value}\n"));
        }
    }

    write_atomic(path, &out)
}

/// Remove keys from a file, keeping comments, ordering and everything else.
///
/// Used when a key is renamed: the old name must not linger next to the new one,
/// or a reader cannot tell which value is current.
pub fn remove_keys(path: &Path, keys: &[&str]) -> io::Result<()> {
    let Ok(existing) = fs::read_to_string(path) else {
        return Ok(());
    };
    let mut out = String::with_capacity(existing.len());
    for line in existing.lines() {
        let name = line.split_once('=').map(|(name, _)| name.trim());
        if name.is_some_and(|name| keys.contains(&name)) {
            continue;
        }
        out.push_str(line);
        out.push('\n');
    }
    if out == existing {
        return Ok(());
    }
    write_atomic(path, &out)
}

/// Replace a file without exposing a partially written version to a reader.
pub fn write_atomic(path: &Path, contents: &str) -> io::Result<()> {
    let parent = path.parent().unwrap_or_else(|| Path::new("."));
    fs::create_dir_all(parent)?;
    let name = path
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .ok_or_else(|| io::Error::other(format!("{} has no file name", path.display())))?;
    let temporary = parent.join(format!(".{name}.{}.tmp", std::process::id()));

    let mode = fs::metadata(path)
        .ok()
        .map(|meta| meta.permissions().mode());
    let result = (|| {
        fs::write(&temporary, contents)?;
        if let Some(mode) = mode {
            fs::set_permissions(&temporary, fs::Permissions::from_mode(mode & 0o7777))?;
        }
        fs::rename(&temporary, path)
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    result
}

/// Owning uid/gid of a directory, so containers can write to it.
pub fn owner(path: &Path) -> (u32, u32) {
    match fs::metadata(path) {
        Ok(meta) => (meta.uid(), meta.gid()),
        Err(_) => current_owner(),
    }
}

/// Fallback when the path does not exist yet: our own uid/gid from /proc.
fn current_owner() -> (u32, u32) {
    if let Ok(status) = fs::read_to_string("/proc/self/status")
        && let Some(line) = status.lines().find(|line| line.starts_with("Uid:"))
    {
        let ids: Vec<u32> = line
            .trim_start_matches("Uid:")
            .split_whitespace()
            .filter_map(|id| id.parse().ok())
            .collect();
        if ids.len() >= 2 {
            return (ids[0], ids[1]);
        }
    }
    (0, 0)
}

fn detect_tz() -> String {
    if let Ok(tz) = std::env::var("TZ")
        && !tz.trim().is_empty()
    {
        return tz;
    }
    if let Ok(contents) = fs::read_to_string("/etc/timezone") {
        let trimmed = contents.trim();
        if !trimmed.is_empty() {
            return trimmed.to_string();
        }
    }
    if let Ok(target) = fs::read_link("/etc/localtime")
        && let Some((_, zone)) = target.to_string_lossy().split_once("zoneinfo/")
    {
        return zone.to_string();
    }
    "UTC".to_string()
}

pub fn timezone() -> String {
    detect_tz()
}

/// Best-effort LAN address of this host.
///
/// Prowlarr (inside gluetun's namespace) and Sonarr/Radarr (in the server
/// stack) sit in different network namespaces, so they cannot use `localhost`
/// to reach each other. The host's LAN address works for both when the stacks
/// share a machine. `CHURN_HOST_IP` overrides detection.
pub fn host_ip() -> String {
    if let Ok(ip) = std::env::var("CHURN_HOST_IP") {
        let ip = ip.trim();
        if !ip.is_empty() {
            return ip.to_string();
        }
    }
    detect_host_ip().unwrap_or_else(|| "127.0.0.1".to_string())
}

/// Ask the kernel which source address it would use for an internet route.
/// Connecting a UDP socket sends no packets, so this is offline-safe.
fn detect_host_ip() -> Option<String> {
    let socket = std::net::UdpSocket::bind("0.0.0.0:0").ok()?;
    socket.connect("1.1.1.1:80").ok()?;
    let address = socket.local_addr().ok()?;
    let ip = address.ip();
    if ip.is_loopback() || ip.is_unspecified() {
        return None;
    }
    Some(ip.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn temp_dir(label: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!("churn-root-{}-{label}", std::process::id()));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        dir
    }

    #[test]
    fn an_explicit_root_override_wins() {
        let cwd = temp_dir("override");
        fs::create_dir_all(cwd.join("server")).unwrap();
        fs::write(cwd.join("server/docker-compose.yml"), "").unwrap();
        fs::create_dir_all(cwd.join("torrent")).unwrap();
        fs::write(cwd.join("torrent/docker-compose.yml"), "").unwrap();

        assert_eq!(
            root_for(Some(OsString::from("/custom/churn")), Some(&cwd)),
            PathBuf::from("/custom/churn")
        );
        fs::remove_dir_all(cwd).unwrap();
    }

    #[test]
    fn a_checkout_is_used_for_development() {
        let cwd = temp_dir("checkout");
        fs::create_dir_all(cwd.join("server")).unwrap();
        fs::write(cwd.join("server/docker-compose.yml"), "").unwrap();
        fs::create_dir_all(cwd.join("torrent")).unwrap();
        fs::write(cwd.join("torrent/docker-compose.yml"), "").unwrap();

        assert_eq!(root_for(None, Some(&cwd)), cwd);
        fs::remove_dir_all(cwd).unwrap();
    }

    #[test]
    fn an_installed_binary_defaults_to_the_system_root() {
        let cwd = temp_dir("installed");
        assert_eq!(root_for(None, Some(&cwd)), PathBuf::from(DEFAULT_ROOT));
        fs::remove_dir_all(cwd).unwrap();
    }
}
